use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fs,path::Path};
mod graph{use serde_json::{json,Value};use std::collections::{BTreeMap,BTreeSet};include!("graph.rs");pub fn inspect(i:&BTreeMap<u64,String>)->BTreeMap<u64,Value>{blocks(i)}}
const R:&str="/home/ubuntu/src/zopro-perf-work/split-redc-callers176";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){assert!(!Path::new(R).join("consumer-chains.json").exists());let old=fs::read_to_string("/home/ubuntu/src/zopro-perf-work/accepted-dependencies176/analyze.rs").unwrap();let from=old.find("fn vector_reg(").unwrap();let to=old.find("fn parser_checks(").unwrap();assert_eq!(fs::read_to_string(format!("{R}/graph.rs")).unwrap(),old[from..to]);let q=read(format!("{R}/qualification.json"));assert_eq!(q["status"],"pass");let mut functions=vec![];for row in q["rows"].as_array().unwrap(){let role=row["role"].as_str().unwrap();let kind=row["kind"].as_str().unwrap();let file=row["inherited_disassembly"].as_str().map(String::from).unwrap_or_else(||format!("{R}/disassembly/{role}-{kind}.txt"));assert_eq!(row["disassembly_sha256"],hash(&file));let start=row["start"].as_u64().unwrap();let end=start+row["size_bytes"].as_u64().unwrap();let mut inst=BTreeMap::new();for l in fs::read_to_string(&file).unwrap().lines(){if let Some((a,s))=l.trim().split_once(':'){if let Ok(a)=u64::from_str_radix(a,16){if a>=start&&a<end{assert!(inst.insert(a,s.trim().to_string()).is_none());}}}}assert_eq!(inst.len()as u64,row["instruction_rows"].as_u64().unwrap());let bs=graph::inspect(&inst);let score=bs.values().map(|v|v["max_connected_calibrated_score"].as_u64().unwrap()).max().unwrap();let selected=bs.values().filter(|v|v["max_connected_calibrated_score"]==score).cloned().collect::<Vec<_>>();functions.push(json!({"role":role,"kind":kind,"source_disassembly":file,"source_sha256":row["disassembly_sha256"],"instruction_rows":inst.len(),"blocks":bs.len(),"calibrated_register_only_rows":bs.values().map(|v|v["calibrated_register_only_rows"].as_u64().unwrap()).sum::<u64>(),"max_connected_calibrated_score":score,"max_score_blocks":selected,"all_blocks":bs.values().collect::<Vec<_>>()}));println!("{role}/{kind}: max connected score {score}");}let out=json!({"status":"pass","functions":functions,"graph_helper_reused_byte_exact":true,"new_decodes":0,"new_profiles":0,"new_proofs":0,"limits":"Same partial register-only connected-subgraph score as prior accepted-dependencies census. Unknown instructions/writers/memory/masks/copies/other immediates/inter-block dependencies omitted; no real cycle, schedule, throughput, spill cost or proof latency prediction. No saved profile transferred to these new binaries."});fs::write(format!("{R}/consumer-chains.json"),serde_json::to_vec_pretty(&out).unwrap()).unwrap();}
